<section class="container py-4"><div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-4"><div><span class="eyebrow">HỒ SƠ KHÁM</span><h1 class="h2 fw-bold">Lần khám #<?= (int)$visit['MaLKham'] ?></h1><p class="text-secondary mb-0"><?= e($visit['TenBenhNhan']) ?> · <?= e($visit['NgayGioKham']) ?></p></div><a class="btn btn-outline-secondary" href="<?= e(url('doctor.visits')) ?>">← Danh sách lịch khám</a></div>
<div class="row g-4"><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-body p-4"><h2 class="h5">Thông tin lần khám</h2><form method="post" action="<?= e(url('doctor.visit.save')) ?>"><?= csrf_field() ?><input type="hidden" name="MaLKham" value="<?= (int)$visit['MaLKham'] ?>"><div class="mb-3"><label class="form-label">Lý do khám</label><input class="form-control" name="LyDoKham" value="<?= e($visit['LyDoKham']) ?>"></div><div class="mb-3"><label class="form-label">Triệu chứng</label><textarea class="form-control" name="TrieuChung" rows="2"><?= e($visit['TrieuChung']) ?></textarea></div><div class="mb-3"><label class="form-label">Chẩn đoán</label><textarea class="form-control" name="ChanDoan" rows="2"><?= e($visit['ChanDoan']) ?></textarea></div><div class="mb-3"><label class="form-label">Kết quả khám</label><textarea class="form-control" name="KetQuaKham" rows="2"><?= e($visit['KetQuaKham']) ?></textarea></div><div class="mb-3"><label class="form-label">Hướng xử lý</label><textarea class="form-control" name="HuongXuLy" rows="2"><?= e($visit['HuongXuLy']) ?></textarea></div><div class="mb-3"><label class="form-label">Ghi chú</label><textarea class="form-control" name="GhiChu" rows="2"><?= e($visit['GhiChu']) ?></textarea></div><div class="mb-3"><label class="form-label">Trạng thái lần khám</label><select class="form-select" name="TrangThaiLanKham"><?php foreach(['DA_TIEP_NHAN'=>'Đã tiếp nhận','DANG_KHAM'=>'Đang khám','DA_HOAN_THANH'=>'Đã hoàn thành'] as $k=>$v): ?><option value="<?= e($k) ?>" <?= $visit['TrangThaiLanKham']===$k?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary">Lưu thông tin khám</button></form></div></div>
<div class="card border-0 shadow-sm mt-4"><div class="card-body p-4"><h2 class="h5">Dịch vụ đã thực hiện</h2><form method="post" action="<?= e(url('doctor.visit.service.add')) ?>" class="row g-2 align-items-end mb-3"><?= csrf_field() ?><input type="hidden" name="MaLKham" value="<?= (int)$visit['MaLKham'] ?>"><div class="col-md-6"><label class="form-label">Dịch vụ</label><select class="form-select" name="MaDV" required><?php foreach ($services as $s): ?><option value="<?= (int)$s['MaDV'] ?>"><?= e($s['TenDV']) ?> · <?= e(money($s['GiaDV'])) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">Số lượng</label><input class="form-control" type="number" min="1" name="SoLuong" value="1" required></div><div class="col-md-4"><label class="form-label">Ghi chú</label><input class="form-control" name="GhiChu"></div><div class="col-12"><button class="btn btn-outline-primary btn-sm">+ Ghi nhận dịch vụ</button></div></form><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Dịch vụ</th><th>Số lượng</th><th>Đơn giá áp dụng</th><th>Thời gian</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= e($item['TenDV']) ?></td><td><?= (int)$item['SoLuong'] ?></td><td><?= e(money($item['DonGiaApDung'])) ?></td><td><?= e($item['ThoiGianThucHien']) ?></td></tr><?php endforeach; ?><?php if (!$items): ?><tr><td colspan="4" class="text-secondary">Chưa ghi nhận dịch vụ.</td></tr><?php endif; ?></tbody></table></div></div></div></div>
<div class="col-lg-5"><div class="card border-0 shadow-sm"><div class="card-body p-4"><h2 class="h5">Đơn thuốc</h2><?php if (!$prescription): ?><p class="text-secondary">Chưa có đơn thuốc cho lần khám này.</p><form method="post" action="<?= e(url('doctor.prescription.create')) ?>"><?= csrf_field() ?><input type="hidden" name="MaLKham" value="<?= (int)$visit['MaLKham'] ?>"><div class="mb-3"><label class="form-label">Lời dặn</label><textarea class="form-control" name="LoiDan" rows="3"></textarea></div><button class="btn btn-primary">Tạo đơn thuốc</button></form><?php else: ?><div class="alert alert-light">Đơn thuốc #<?= (int)$prescription['MaDonThuoc'] ?> · <?= e($prescription['NgayKeDon']) ?></div><form method="post" action="<?= e(url('doctor.medicine.add')) ?>"><?= csrf_field() ?><input type="hidden" name="MaLKham" value="<?= (int)$visit['MaLKham'] ?>"><input type="hidden" name="MaDonThuoc" value="<?= (int)$prescription['MaDonThuoc'] ?>"><div class="mb-2"><label class="form-label">Tên thuốc</label><input class="form-control" name="TenThuoc" required></div><div class="mb-2"><label class="form-label">Số lượng</label><input class="form-control" type="number" min="0.01" step="0.01" name="SoLuong" required></div><div class="mb-2"><label class="form-label">Liều lượng</label><input class="form-control" name="LieuLuong"></div><div class="mb-2"><label class="form-label">Cách dùng</label><input class="form-control" name="CachDung"></div><div class="row g-2"><div class="col-6"><label class="form-label">Bắt đầu</label><input class="form-control" type="date" name="ThoiGianBatDau"></div><div class="col-6"><label class="form-label">Kết thúc</label><input class="form-control" type="date" name="ThoiGianKetThuc"></div></div><button class="btn btn-outline-primary btn-sm mt-3">+ Thêm thuốc</button></form><hr><h3 class="h6">Chi tiết thuốc</h3><?php foreach ($medicines as $m): ?><div class="medicine-row"><strong><?= e($m['TenThuoc']) ?></strong><div class="small text-secondary">SL: <?= e($m['SoLuong']) ?> · <?= e($m['LieuLuong']) ?> · <?= e($m['CachDung']) ?></div><div class="small text-secondary"><?= e($m['ThoiGianBatDau']) ?> – <?= e($m['ThoiGianKetThuc']) ?></div></div><?php endforeach; ?><?php if (!$medicines): ?><p class="small text-secondary">Chưa có thuốc trong đơn.</p><?php endif; ?><?php endif; ?></div></div><div class="alert alert-warning small mt-3">Thông tin chẩn đoán và kê đơn là dữ liệu chuyên môn. Chỉ nhập dữ liệu giả lập khi thử nghiệm đồ án; không dùng dữ liệu bệnh nhân thật.</div></div></div></section>
